//! The two generated files' text, from the model.

use crate::model::{Field, Model, Record};

/// What every generated file starts with.
const GENERATED: &str =
    "// @generated by crates/present-gen from ui/types.slint and ui/state.slint: run `just present`
// rather than editing this file.
";

/// Fields the Slint window draws in its own way, by a function of `ui/mod.rs`: a text block's
/// paragraphs, which Slint draws with no space between them, and a code block's colours.
const DRAWN_BY_THE_WINDOW: [(&str, &str); 1] = [("MdBlock", "body")];

/// `kebab-case` to `CamelCase`.
fn camel(name: &str) -> String {
    name.split('-')
        .map(|part| {
            let mut letters = part.chars();
            letters
                .next()
                .map(|first| first.to_uppercase().chain(letters).collect::<String>())
                .unwrap_or_default()
        })
        .collect()
}

/// `kebab-case` to `snake_case`.
fn snake(name: &str) -> String {
    name.replace('-', "_")
}

fn derives(model: &Model, fields: &[Field]) -> String {
    let eq = !fields.iter().any(|field| model.has_float(&field.kind));
    let mut items = vec!["Debug", "Clone", "Default", "PartialEq"];
    if eq {
        items.push("Eq");
    }
    format!("#[derive({})]", items.join(", "))
}

fn rust_record(model: &Model, record: &Record, out: &mut Vec<String>) {
    out.push(derives(model, &record.fields));
    out.push(format!("pub struct {} {{", record.name));
    for field in &record.fields {
        out.push(format!(
            "    pub {}: {},",
            snake(&field.name),
            field.kind.rust()
        ));
    }
    out.push("}\n".to_owned());
}

/// `crates/core/src/present/model.rs`: the model as plain Rust data, which the presenter fills
/// and every frontend shows.
pub fn present(model: &Model) -> String {
    let mut out = vec![format!(
        "{GENERATED}
//! What the window shows, as plain data: the same types as the Slint window's, which every
//! frontend shows. It never leaves the process, so it has no serde.

use super::{{Image, Styled}};
"
    )];
    for item in &model.enums {
        out.push(format!(
            "#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash)]\npub enum {} {{",
            item.name
        ));
        for (index, value) in item.values.iter().enumerate() {
            if index == 0 {
                out.push("    #[default]".to_owned());
            }
            out.push(format!("    {},", camel(value)));
        }
        out.push("}\n".to_owned());
    }
    for record in &model.structs {
        rust_record(model, record, &mut out);
    }
    for record in &model.globals {
        out.push(format!("/// The `{}` global's state.", record.name));
        rust_record(model, record, &mut out);
    }
    out.join("\n")
}

/// `crates/slint/src/ui/model.rs`: the model as Slint's types, and each presented global brought
/// in line with a new state, setting only what changed and changing list models row by row (a
/// row that stays keeps its selection and what was typed into it).
pub fn slint(model: &Model) -> String {
    let mut out = vec![format!(
        "{GENERATED}
//! The presentation model as Slint's types, and the window's globals brought in line with it.

use slint::ComponentHandle;

use super::{{Drawing, ToSlint, md_body, resync}};
use crate::generated::{{self as slint_ui, AppWindow}};
use crate::present::model as present;
"
    )];
    for item in &model.enums {
        let name = &item.name;
        out.push(format!(
            "impl ToSlint for present::{name} {{\n    type Slint = slint_ui::{name};\n    fn to_slint(&self, _: &Drawing) -> Self::Slint {{\n        match self {{"
        ));
        for value in &item.values {
            let value = camel(value);
            out.push(format!(
                "            Self::{value} => slint_ui::{name}::{value},"
            ));
        }
        out.push("        }\n    }\n}\n".to_owned());
    }
    for record in &model.structs {
        let name = &record.name;
        out.push(format!(
            "impl ToSlint for present::{name} {{\n    type Slint = slint_ui::{name};\n    fn to_slint(&self, images: &Drawing) -> Self::Slint {{\n        slint_ui::{name} {{"
        ));
        for field in &record.fields {
            let field_name = snake(&field.name);
            if DRAWN_BY_THE_WINDOW.contains(&(name.as_str(), field.name.as_str())) {
                out.push(format!("            {field_name}: md_body(self, images),"));
            } else {
                out.push(format!(
                    "            {field_name}: self.{field_name}.to_slint(images),"
                ));
            }
        }
        out.push("        }\n    }".to_owned());
        // A row brought in line in place: its lists keep their models.
        if record.fields.iter().any(|field| field.kind.is_list()) {
            out.push(
                "    fn sync(&self, old: &Self, shown: Self::Slint, images: &Drawing) -> Self::Slint {"
                    .to_owned(),
            );
            out.push("        let mut row = self.to_slint(images);".to_owned());
            for field in record.fields.iter().filter(|field| field.kind.is_list()) {
                let f = snake(&field.name);
                out.push(format!(
                    "        row.{f} = resync(&shown.{f}, &old.{f}, &self.{f}, images).unwrap_or(shown.{f});"
                ));
            }
            out.push("        row\n    }\n}\n".to_owned());
        } else {
            out.push("}\n".to_owned());
        }
    }
    for record in &model.globals {
        let name = &record.name;
        out.push(format!(
            "/// Brings the `{name}` global in line with `new`, setting what differs from `old` (all,\n/// for none)."
        ));
        out.push(format!(
            "pub(super) fn apply_{}(window: &AppWindow, old: Option<&present::{name}>, new: &present::{name}, images: &Drawing) {{",
            snake(name).to_lowercase()
        ));
        out.push(format!(
            "    let global = window.global::<slint_ui::{name}>();"
        ));
        for field in &record.fields {
            let f = snake(&field.name);
            if field.kind.is_list() {
                out.push(format!(
                    "    match old {{\n        Some(old) if old.{f} != new.{f} => {{\n            if let Some(model) = resync(&global.get_{f}(), &old.{f}, &new.{f}, images) {{\n                global.set_{f}(model);\n            }}\n        }}\n        Some(_) => {{}}\n        None => global.set_{f}(new.{f}.to_slint(images)),\n    }}"
                ));
            } else {
                out.push(format!(
                    "    if old.is_none_or(|old| old.{f} != new.{f}) {{\n        global.set_{f}(new.{f}.to_slint(images));\n    }}"
                ));
            }
        }
        out.push("}\n".to_owned());
    }
    out.join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Slint's names become Rust's: kebab-case values to CamelCase variants, fields to
    /// snake_case.
    #[test]
    fn renames_slint_names_for_rust() {
        assert_eq!(camel("loud-and-clear"), "LoudAndClear");
        assert_eq!(camel("quiet"), "Quiet");
        assert_eq!(snake("scroll-to-end"), "scroll_to_end");
    }
}
